// Spawn hazards
spawnTimer -= dt;
if (spawnTimer <= 0) {
  spawnTimer = SPAWN_INTERVAL;
  const angle = Math.random() * Math.PI * 2;
  const distance = Math.max(SAFE_RADIUS, Math.hypot(canvas.width, canvas.height));
  const x = player.x + Math.cos(angle) * distance;
  const y = player.y + Math.sin(angle) * distance;
  const speed = 150;
  const dirX = player.x - x;
  const dirY = player.y - y;
  const len = Math.hypot(dirX, dirY);
  const vx = (dirX / len) * speed;
  const vy = (dirY / len) * speed;
  hazards.push({ x, y, vx, vy, radius: 8, alive: true });
}

// Update hazards
for (const h of hazards) {
  if (!h.alive) continue;
  h.x += h.vx * dt;
  h.y += h.vy * dt;
  // collision with player
  const dx = h.x - player.x;
  const dy = h.y - player.y;
  const dist = Math.hypot(dx, dy);
  if (dist < h.radius + player.radius) {
    phase = "gameover";
    h.alive = false;
  }
}

// Spawn hazards
spawnTimer -= dt;
if (spawnTimer <= 0) {
  spawnTimer = SPAWN_INTERVAL;
  // Random angle and distance
  const angle = Math.random() * Math.PI * 2;
  const distance = Math.max(SAFE_RADIUS, Math.hypot(canvas.width, canvas.height));
  const x = player.x + Math.cos(angle) * distance;
  const y = player.y + Math.sin(angle) * distance;
  const speed = 150; // px/sec
  const vx = (player.x - x) / Math.hypot(player.x - x, player.y - y) * speed;
  const vy = (player.y - y) / Math.hypot(player.x - x, player.y - y) * speed;
  hazards.push({ x, y, vx, vy, radius: 8, alive: true });
}

// Player movement based on keys
const accel = 800; // px/sec^2
const maxSpeed = 400; // px/sec
const friction = 0.9;
let ax = 0, ay = 0;
if (keys.has('ArrowLeft') || keys.has('a') || keys.has('A')) ax -= accel;
if (keys.has('ArrowRight') || keys.has('d') || keys.has('D')) ax += accel;
if (keys.has('ArrowUp') || keys.has('w') || keys.has('W')) ay -= accel;
if (keys.has('ArrowDown') || keys.has('s') || keys.has('S')) ay += accel;
// apply acceleration
player.vx = (player.vx || 0) + ax * dt;
player.vy = (player.vy || 0) + ay * dt;
// clamp speed
const speed = Math.hypot(player.vx, player.vy);
if (speed > maxSpeed) {
  player.vx = (player.vx / speed) * maxSpeed;
  player.vy = (player.vy / speed) * maxSpeed;
}
// apply friction
player.vx *= friction;
player.vy *= friction;
// update position
player.x += player.vx * dt;
player.y += player.vy * dt;
// clamp within canvas
player.x = Math.max(player.radius, Math.min(canvas.width - player.radius, player.x));
player.y = Math.max(player.radius, Math.min(canvas.height - player.radius, player.y));

